-- SOURCE: 20260709120000_customer_cards_foundation.sql
-- Original SHA-256: 4e561974f6bd0cb9c372772b543cec0daeed187ac516f8acbcc70138d803ec06
-- ServiceOS — Signal Processing & Customer Cards Foundation v1.
--
-- The platform is moving from "sync records" to "process signals": every canonical
-- interaction (phone/email now; Slack/forms/WhatsApp later) becomes a signal that
-- helps build cleaner customer/company/job/task cards over time. This migration
-- lays the DATA foundation only — no CRM logic, no AI matching, no fake data.
--
-- New tables (all additive, non-destructive):
--   • companies                     — organisations
--   • people                        — individuals (optionally linked to a company)
--   • customer_cards                — the operational "what needs attention" card
--   • interaction_match_suggestions — evidence-led link proposals (never silent merges)
--
-- The existing `interactions` table already carries the link columns
-- (related_person_id / related_company_id / related_job_id / related_task_id) and
-- processing_status/priority — this migration provides their targets. Nothing is
-- populated here; a future enrichment/matching phase fills these safely.
--
-- RLS: tenant-scoped SELECT for authenticated users; NO write policies (service
-- role Edge Functions own writes). Reuses set_updated_at() + current_tenant_id().
-- Status/priority/level values are conventions documented inline (free text, like
-- the rest of the schema) — no premature CHECK constraints.

-- ---------------------------------------------------------------------------
-- companies
-- ---------------------------------------------------------------------------
create table if not exists companies (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null,
  name         text not null,
  domain       text,
  phone        text,
  address_text text,
  postcode     text,
  metadata     jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index if not exists companies_tenant_idx on companies (tenant_id);
create index if not exists companies_tenant_domain_idx on companies (tenant_id, domain);

drop trigger if exists companies_set_updated_at on companies;
create trigger companies_set_updated_at
  before update on companies for each row execute function set_updated_at();
alter table companies enable row level security;

-- ---------------------------------------------------------------------------
-- people
-- ---------------------------------------------------------------------------
create table if not exists people (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null,
  company_id    uuid references companies (id) on delete set null,
  display_name  text,
  first_name    text,
  last_name     text,
  primary_email text,
  primary_phone text,
  address_text  text,
  postcode      text,
  metadata      jsonb not null default '{}'::jsonb,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index if not exists people_tenant_idx on people (tenant_id);
create index if not exists people_tenant_email_idx on people (tenant_id, primary_email);
create index if not exists people_tenant_phone_idx on people (tenant_id, primary_phone);
create index if not exists people_tenant_company_idx on people (tenant_id, company_id);

drop trigger if exists people_set_updated_at on people;
create trigger people_set_updated_at
  before update on people for each row execute function set_updated_at();
alter table people enable row level security;

-- ---------------------------------------------------------------------------
-- customer_cards — the daily "what needs attention" surface (foundation only).
-- status   (traffic-light): grey | green | amber | red
-- priority (queue):         critical | high | medium | low | waiting | done
-- ---------------------------------------------------------------------------
create table if not exists customer_cards (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null,
  person_id          uuid references people (id) on delete set null,
  company_id         uuid references companies (id) on delete set null,
  title              text,
  summary            text,
  status             text not null default 'grey',
  priority           text not null default 'medium',
  owner_id           uuid,                         -- profiles.id (no FK: avoids auth coupling)
  due_at             timestamptz,
  latest_activity_at timestamptz,
  recommended_action text,
  context            jsonb not null default '{}'::jsonb,
  completed_at       timestamptz,
  metadata           jsonb not null default '{}'::jsonb,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index if not exists customer_cards_tenant_status_idx on customer_cards (tenant_id, status);
create index if not exists customer_cards_tenant_priority_idx on customer_cards (tenant_id, priority);
create index if not exists customer_cards_tenant_person_idx on customer_cards (tenant_id, person_id);
create index if not exists customer_cards_tenant_company_idx on customer_cards (tenant_id, company_id);
create index if not exists customer_cards_tenant_activity_idx
  on customer_cards (tenant_id, latest_activity_at desc);

drop trigger if exists customer_cards_set_updated_at on customer_cards;
create trigger customer_cards_set_updated_at
  before update on customer_cards for each row execute function set_updated_at();
alter table customer_cards enable row level security;

-- ---------------------------------------------------------------------------
-- interaction_match_suggestions — evidence-led link proposals. The system NEVER
-- silently merges on weak AI evidence: matches are proposed here with a confidence
-- score, the evidence used, an explanation and a recommended action, and a human
-- (or a strong-evidence auto-linker, later) resolves them.
-- match_level: confirmed | likely | possible | rejected
-- status:      pending | accepted | rejected | superseded
-- target_type: person | company | customer_card | interaction
-- ---------------------------------------------------------------------------
create table if not exists interaction_match_suggestions (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null,
  interaction_id     uuid not null references interactions (id) on delete cascade,
  target_type        text not null,
  target_id          uuid,
  match_level        text not null default 'possible',
  confidence         numeric(5, 4),               -- 0.0000–1.0000
  evidence           jsonb not null default '{}'::jsonb, -- signals used (email/phone/name/…)
  explanation        text,
  recommended_action text,
  status             text not null default 'pending',
  created_by         text,                        -- 'ai' | 'system' | user id
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique (tenant_id, interaction_id, target_type, target_id)
);
create index if not exists ims_tenant_status_idx
  on interaction_match_suggestions (tenant_id, status);
create index if not exists ims_tenant_level_idx
  on interaction_match_suggestions (tenant_id, match_level);
create index if not exists ims_tenant_interaction_idx
  on interaction_match_suggestions (tenant_id, interaction_id);

drop trigger if exists ims_set_updated_at on interaction_match_suggestions;
create trigger ims_set_updated_at
  before update on interaction_match_suggestions for each row execute function set_updated_at();
alter table interaction_match_suggestions enable row level security;

-- ---------------------------------------------------------------------------
-- Tenant-scoped SELECT policies (read-only). Writes are service-role via Edge
-- Functions — no direct client writes, no cross-tenant leakage.
-- ---------------------------------------------------------------------------
drop policy if exists companies_select_tenant on companies;
create policy companies_select_tenant on companies
  for select to authenticated using (tenant_id = current_tenant_id());

drop policy if exists people_select_tenant on people;
create policy people_select_tenant on people
  for select to authenticated using (tenant_id = current_tenant_id());

drop policy if exists customer_cards_select_tenant on customer_cards;
create policy customer_cards_select_tenant on customer_cards
  for select to authenticated using (tenant_id = current_tenant_id());

drop policy if exists ims_select_tenant on interaction_match_suggestions;
create policy ims_select_tenant on interaction_match_suggestions
  for select to authenticated using (tenant_id = current_tenant_id());

-- SOURCE: 20260709140000_identity_engine.sql
-- Original SHA-256: 35a6766e84a86651e2a3e38eaf33239797adb3d76f3e71da2fccc8b8ecddb69a
-- ServiceOS — Identity Resolution Engine v1 (evidence engine, not CRM matching).
--
-- Every new interaction asks: who is this? what company? what site? what job? what
-- previous conversations? what next? The answers are EVIDENCE-LED — every match
-- stores its evidence, an explanation and a confidence, is explainable, and is
-- reversible. Nothing is silently merged on weak evidence, and nothing is faked.
--
-- This migration is additive/non-destructive foundation:
--   • recommendations                — the recommendation engine's output
--   • customer_cards: ownership + a live priority score + locked_fields (protect
--     manually-confirmed data) + identity confidence
--   • people / companies: verified + created_source (mark auto-provisioned records)
--
-- The generic `context` jsonb already on customer_cards is the Commusoft-ready
-- linking model (jobs/sites/assets/engineers/quotes/invoices/service_history/
-- documents/photos). RLS: tenant-scoped SELECT; service-role writes. Reuses
-- set_updated_at() + current_tenant_id().

-- ---------------------------------------------------------------------------
-- recommendations — computed, explainable next-actions (never auto-executed in v1)
-- severity: critical | high | medium | low | info
-- status:   open | actioned | dismissed | expired
-- ---------------------------------------------------------------------------
create table if not exists recommendations (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null,
  type               text not null,                 -- e.g. repeat_contact_today | review_new_contact
  title              text not null,
  detail             text,
  severity           text not null default 'medium',
  status             text not null default 'open',
  card_id            uuid references customer_cards (id) on delete cascade,
  interaction_id     uuid references interactions (id) on delete set null,
  person_id          uuid,
  company_id         uuid,
  evidence           jsonb not null default '[]'::jsonb,
  recommended_action text,
  confidence         numeric,
  created_by         text not null default 'system', -- system | ai | user id
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  resolved_at        timestamptz
);
create index if not exists recommendations_tenant_status_idx
  on recommendations (tenant_id, status, created_at desc);
create index if not exists recommendations_tenant_type_idx on recommendations (tenant_id, type);
create index if not exists recommendations_tenant_card_idx on recommendations (tenant_id, card_id);
-- At most one OPEN recommendation of a given type per card → idempotent generation.
create unique index if not exists recommendations_open_uk
  on recommendations (tenant_id, card_id, type)
  where status = 'open' and card_id is not null;

drop trigger if exists recommendations_set_updated_at on recommendations;
create trigger recommendations_set_updated_at
  before update on recommendations for each row execute function set_updated_at();
alter table recommendations enable row level security;

drop policy if exists recommendations_select_tenant on recommendations;
create policy recommendations_select_tenant on recommendations
  for select to authenticated using (tenant_id = current_tenant_id());

-- ---------------------------------------------------------------------------
-- customer_cards — ownership, live priority, and protection of manual data.
-- ---------------------------------------------------------------------------
alter table customer_cards
  add column if not exists assigned_team_id   uuid,
  add column if not exists watchers           jsonb   not null default '[]'::jsonb,
  add column if not exists followers          jsonb   not null default '[]'::jsonb,
  add column if not exists helper_suggestions jsonb   not null default '[]'::jsonb,
  add column if not exists priority_score     numeric,
  add column if not exists priority_inputs    jsonb   not null default '{}'::jsonb,
  -- Column names a human has manually confirmed — the engine NEVER overwrites these.
  add column if not exists locked_fields      text[]  not null default '{}',
  add column if not exists confidence         numeric;

create index if not exists customer_cards_tenant_score_idx
  on customer_cards (tenant_id, priority_score desc);

-- ---------------------------------------------------------------------------
-- people / companies — provenance so auto-provisioned records are honest.
-- created_source: interaction | manual | import
-- ---------------------------------------------------------------------------
alter table people
  add column if not exists verified       boolean not null default false,
  add column if not exists created_source text;

alter table companies
  add column if not exists verified       boolean not null default false,
  add column if not exists created_source text;

-- SOURCE: 20260709160000_business_graph.sql
-- Original SHA-256: ab482bc5f81b7836136e7e53843d977fb7cfdc3d0d9f8ee823f0e9cfb228f221
-- ServiceOS — Business Graph v1 (the shared memory layer).
--
-- The canonical relationship layer shared by ServiceOS, ProductOS and future
-- OpenFolk products. Everything in the business becomes a NODE (person, company,
-- customer_card, interaction, recommendation, … and later site/job/asset/…), an
-- EDGE (person works_for company, interaction relates_to card, …) or an EVENT
-- (node.created, edge.created, graph.enriched, graph.conflict_detected).
--
-- v1 is a PROJECTION layer: the existing people/companies/customer_cards/
-- interactions/recommendations tables remain the system of record and are NEVER
-- modified. `business-graph-sync` projects them into the graph idempotently, keyed
-- by (source_table, source_id). Non-destructive & additive. There is no graph
-- reasoning engine yet — this is the durable substrate future dashboards, cards,
-- recommendations and automations read from.
--
-- RLS: tenant-scoped SELECT for authenticated users; NO write policies (service
-- role Edge Functions own all writes, bypassing RLS). Reuses set_updated_at()
-- (Phone-0) and current_tenant_id() (Security-2). No cross-tenant edges: both
-- endpoints of an edge are always written under the same tenant_id.

-- ── graph_nodes ────────────────────────────────────────────────────────────
create table if not exists graph_nodes (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null,
  node_type    text not null,                    -- person | company | customer_card | interaction | recommendation | …
  source_table text,                             -- system-of-record table (null for synthetic nodes)
  source_id    uuid,                             -- PK in source_table (null for synthetic nodes)
  external_ref text,                             -- optional external identifier
  label        text,                             -- human label (never secret/content)
  status       text not null default 'active',
  confidence   numeric,                          -- null = unknown (never fabricate certainty)
  properties   jsonb not null default '{}'::jsonb,
  metadata     jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

-- One node per system-of-record row (idempotent projection key). Partial because
-- synthetic nodes may have no source.
create unique index if not exists graph_nodes_source_uk
  on graph_nodes (tenant_id, node_type, source_table, source_id)
  where source_id is not null;

create index if not exists graph_nodes_tenant_type_idx on graph_nodes (tenant_id, node_type);
create index if not exists graph_nodes_tenant_source_idx
  on graph_nodes (tenant_id, source_table, source_id);
create index if not exists graph_nodes_tenant_created_idx on graph_nodes (tenant_id, created_at desc);

drop trigger if exists graph_nodes_set_updated_at on graph_nodes;
create trigger graph_nodes_set_updated_at
  before update on graph_nodes
  for each row execute function set_updated_at();

alter table graph_nodes enable row level security;
drop policy if exists graph_nodes_select_tenant on graph_nodes;
create policy graph_nodes_select_tenant on graph_nodes
  for select to authenticated using (tenant_id = current_tenant_id());

-- ── graph_edges ────────────────────────────────────────────────────────────
create table if not exists graph_edges (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null,
  edge_type    text not null,                    -- works_for | contacted | relates_to | represents | concerns | …
  from_node_id uuid not null references graph_nodes (id) on delete cascade,
  to_node_id   uuid not null references graph_nodes (id) on delete cascade,
  confidence   numeric,                          -- 1.0 for direct FK edges; lower for inferred; null = unknown
  evidence     jsonb not null default '[]'::jsonb,
  status       text not null default 'active',
  properties   jsonb not null default '{}'::jsonb,
  metadata     jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

-- One edge per (type, from, to) — idempotent.
create unique index if not exists graph_edges_uk
  on graph_edges (tenant_id, edge_type, from_node_id, to_node_id);

create index if not exists graph_edges_tenant_from_idx on graph_edges (tenant_id, from_node_id);
create index if not exists graph_edges_tenant_to_idx on graph_edges (tenant_id, to_node_id);
create index if not exists graph_edges_tenant_type_idx on graph_edges (tenant_id, edge_type);
create index if not exists graph_edges_tenant_created_idx on graph_edges (tenant_id, created_at desc);

drop trigger if exists graph_edges_set_updated_at on graph_edges;
create trigger graph_edges_set_updated_at
  before update on graph_edges
  for each row execute function set_updated_at();

alter table graph_edges enable row level security;
drop policy if exists graph_edges_select_tenant on graph_edges;
create policy graph_edges_select_tenant on graph_edges
  for select to authenticated using (tenant_id = current_tenant_id());

-- ── graph_events ───────────────────────────────────────────────────────────
-- Append-only log of graph mutations (visibility, and the seed for future
-- graph-driven subscribers). No updated_at — events are immutable.
create table if not exists graph_events (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null,
  event_type      text not null,                 -- node.created | node.updated | edge.created | edge.updated | graph.enriched | graph.conflict_detected
  node_id         uuid,                          -- soft ref (no FK: events outlive nodes)
  edge_id         uuid,                          -- soft ref
  source_event_id uuid,                          -- e.g. the platform_events interaction.ready that triggered this
  payload         jsonb not null default '{}'::jsonb,
  created_at      timestamptz not null default now()
);

create index if not exists graph_events_tenant_type_created_idx
  on graph_events (tenant_id, event_type, created_at desc);
create index if not exists graph_events_tenant_node_idx on graph_events (tenant_id, node_id);
create index if not exists graph_events_tenant_edge_idx on graph_events (tenant_id, edge_id);

alter table graph_events enable row level security;
drop policy if exists graph_events_select_tenant on graph_events;
create policy graph_events_select_tenant on graph_events
  for select to authenticated using (tenant_id = current_tenant_id());

-- SOURCE: 20260716120100_operating_profile.sql
-- Original SHA-256: bb559b7d9745f9901513060c5cde5130f1fa8a6e7f34024789017fa9b14da856
-- ============================================================================
-- Universal Intelligence Foundation — P1 TENANT OPERATING PROFILE (layered)
-- ============================================================================
-- The profile is not one blob. It is resolved from ordered layers (platform →
-- industry → domain → tenant → department → team → user) into an effective
-- snapshot. Industry is a DATA layer, never a code path — this is the structural
-- guarantee behind "no hard-coded industries". See docs §2.
-- ============================================================================

-- ── Org structure that needs referential integrity (kinds are DATA). ────────
create table if not exists org_units (
  id         uuid primary key default gen_random_uuid(),
  tenant_id  uuid not null references tenants(id) on delete cascade,
  kind       text not null,                 -- 'department' | 'team' | 'crew' | ... (from pack/profile)
  parent_id  uuid references org_units(id) on delete set null,
  name       text not null,
  metadata   jsonb not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists org_units_tenant on org_units (tenant_id);

create table if not exists org_unit_members (
  org_unit_id uuid not null references org_units(id) on delete cascade,
  user_id     uuid not null references profiles(id) on delete cascade,
  role_in_unit text,                          -- 'lead' | 'member' | ... (data)
  created_at  timestamptz not null default now(),
  primary key (org_unit_id, user_id)
);

-- ── Every profile fact is a scoped, versioned key/value. Scope = the layer. ──
-- The brief's long list (SLA, escalation, approval, AI permissions, risk
-- appetite, confidence thresholds, terminology, ...) are NAMESPACES, not columns.
create table if not exists operating_profile_entries (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid references tenants(id) on delete cascade,   -- null = platform/industry default
  scope_kind  text not null
                check (scope_kind in ('platform','industry','domain','tenant','department','team','user')),
  scope_ref   text,                            -- industry key / domain id / org_unit id / user id
  domain      text,                            -- null = applies to all domains
  namespace   text not null,                   -- 'sla' | 'escalation' | 'ai_permissions' | 'confidence' | ...
  key         text not null,
  value       jsonb not null,
  version_id  uuid not null references config_versions(id),
  created_at  timestamptz not null default now()
);
create index if not exists ope_lookup on operating_profile_entries (tenant_id, namespace, key);
create index if not exists ope_scope  on operating_profile_entries (scope_kind, scope_ref, domain);
-- Natural key (nullable parts coalesced) so seeds are idempotent under re-apply.
create unique index if not exists ope_natural_uk on operating_profile_entries (
  coalesce(tenant_id, '00000000-0000-0000-0000-000000000000'::uuid),
  scope_kind, coalesce(scope_ref, ''), coalesce(domain, ''), namespace, key
);

-- ── The resolved snapshot the ENGINE reads (never re-derives from tenant id). ─
-- input_hash makes point-in-time replay possible (simulation, §10.2).
create table if not exists effective_profiles (
  tenant_id   uuid not null references tenants(id) on delete cascade,
  domain      text not null,
  resolved    jsonb not null,                  -- deep-merged layers
  input_hash  text not null,                   -- hash of contributing version ids
  computed_at timestamptz not null default now(),
  primary key (tenant_id, domain)
);

-- ── RLS ─────────────────────────────────────────────────────────────────────
alter table org_units enable row level security;
drop policy if exists org_units_select on org_units;
create policy org_units_select on org_units for select to authenticated
  using (tenant_id = current_tenant_id() or is_openfolk());

alter table org_unit_members enable row level security;
drop policy if exists org_unit_members_select on org_unit_members;
create policy org_unit_members_select on org_unit_members for select to authenticated
  using (exists (select 1 from org_units u
                 where u.id = org_unit_id
                   and (u.tenant_id = current_tenant_id() or is_openfolk())));

alter table operating_profile_entries enable row level security;
drop policy if exists ope_select on operating_profile_entries;
create policy ope_select on operating_profile_entries for select to authenticated
  using (tenant_id is null or tenant_id = current_tenant_id() or is_openfolk());

alter table effective_profiles enable row level security;
drop policy if exists effprof_select on effective_profiles;
create policy effprof_select on effective_profiles for select to authenticated
  using (tenant_id = current_tenant_id() or is_openfolk());

-- ── triggers ────────────────────────────────────────────────────────────────
drop trigger if exists org_units_set_updated_at on org_units;
create trigger org_units_set_updated_at before update on org_units
  for each row execute function set_updated_at();

-- SOURCE: 20260716120200_intelligence_objects.sql
-- Original SHA-256: 6d1713eec44ae73ba374b4a3f2fa78618f27bec9b4d467c63cb78ce76bd3b52f
-- ============================================================================
-- Universal Intelligence Foundation — P2 INTELLIGENCE OBJECTS + STATE ENGINE
-- ============================================================================
-- One table, one language. object_type is DATA (domain_object_types), not an
-- enum, so ServiceOS/ProductOS add types without a migration. attributes jsonb
-- is validated per-type by a pack-supplied JSON Schema. Generalizes the existing
-- `recommendations` table (which becomes one object_type via the compat layer).
-- See docs §3, §4.
-- ============================================================================

create table if not exists intelligence_objects (
  id                  uuid primary key default gen_random_uuid(),
  tenant_id           uuid not null references tenants(id) on delete cascade,
  domain              text not null,               -- 'core' | 'serviceos' | 'productos'
  object_type         text not null,               -- Task|Commitment|Blocker|Risk|... (pack-registered)
  subject             text not null,
  -- ownership HOT cache (authoritative full RACI lives in ownership_assignments)
  responsible_ref     jsonb,                        -- {kind, ref}
  accountable_ref     jsonb,
  waiting_on_ref      jsonb,
  -- scoring inputs for confidence routing (§6.2)
  priority            text,                         -- pack-defined vocabulary
  severity            text,
  confidence          numeric check (confidence   is null or (confidence   between 0 and 1)),
  ambiguity           numeric check (ambiguity    is null or (ambiguity    between 0 and 1)),
  risk                numeric check (risk         is null or (risk         between 0 and 1)),
  reversibility       numeric check (reversibility is null or (reversibility between 0 and 1)),
  -- lifecycle
  status              text not null default 'unknown',   -- UNIVERSAL state
  domain_state        text,                          -- pack sub-state (nullable)
  deadline            timestamptz,
  blocking            uuid[] not null default '{}',  -- other objects this one blocks
  -- provenance / evidence
  evidence            jsonb not null default '[]',   -- [{source, detail}] — existing shared primitive
  source_interactions uuid[] not null default '{}',  -- interactions.id[]
  source_entities     uuid[] not null default '{}',  -- graph_nodes.id[]
  created_by          text,                          -- system|ai|<user id>
  created_from        text,                          -- extractor/rule name
  policy_applied      uuid,                          -- policies.id that decided this (soft ref)
  decision_id         uuid,                          -- decision_log.id (soft ref)
  attributes          jsonb not null default '{}',   -- type-specific, JSON-Schema validated by the pack
  version             int  not null default 1,       -- object revision (optimistic concurrency)
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create index if not exists io_lookup   on intelligence_objects (tenant_id, domain, object_type, status);
create index if not exists io_deadline on intelligence_objects (tenant_id, status, deadline);
create index if not exists io_entities on intelligence_objects using gin (source_entities);
create index if not exists io_srcint   on intelligence_objects using gin (source_interactions);

-- ── Object-type registry (core seeds the 22; packs extend). ─────────────────
create table if not exists domain_object_types (
  domain            text not null,
  object_type       text not null,
  label             text not null,
  attributes_schema jsonb not null default '{}',   -- JSON Schema for intelligence_objects.attributes
  description       text,
  primary key (domain, object_type)
);

-- ── Universal states + DATA-driven domain state machines (§4). ──────────────
create table if not exists state_definitions (
  domain           text not null,
  object_type      text not null,
  state            text not null,
  maps_to_universal text not null,              -- every domain state rolls up to a core state
  is_terminal      boolean not null default false,
  primary key (domain, object_type, state)
);
create table if not exists state_transitions (
  domain      text not null,
  object_type text not null,
  from_state  text not null,
  to_state    text not null,
  guard       jsonb,                            -- optional declarative condition
  primary key (domain, object_type, from_state, to_state)
);

-- ── Append-only transition history (audit + simulation substrate). ──────────
create table if not exists object_state_history (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references tenants(id) on delete cascade,
  object_id   uuid not null references intelligence_objects(id) on delete cascade,
  from_state  text,
  to_state    text not null,
  actor       jsonb,
  reason      text,
  decision_id uuid,
  occurred_at timestamptz not null default now()
);
create index if not exists osh_object on object_state_history (object_id, occurred_at);

-- ── RLS ─────────────────────────────────────────────────────────────────────
alter table intelligence_objects enable row level security;
drop policy if exists io_select on intelligence_objects;
create policy io_select on intelligence_objects for select to authenticated
  using (tenant_id = current_tenant_id() or is_openfolk());

alter table object_state_history enable row level security;
drop policy if exists osh_select on object_state_history;
create policy osh_select on object_state_history for select to authenticated
  using (tenant_id = current_tenant_id() or is_openfolk());

-- Registries are non-secret platform metadata: readable by any authenticated user.
alter table domain_object_types enable row level security;
drop policy if exists dot_select on domain_object_types;
create policy dot_select on domain_object_types for select to authenticated using (true);

alter table state_definitions enable row level security;
drop policy if exists sd_select on state_definitions;
create policy sd_select on state_definitions for select to authenticated using (true);

alter table state_transitions enable row level security;
drop policy if exists st_select on state_transitions;
create policy st_select on state_transitions for select to authenticated using (true);

-- ── triggers ────────────────────────────────────────────────────────────────
drop trigger if exists io_set_updated_at on intelligence_objects;
create trigger io_set_updated_at before update on intelligence_objects
  for each row execute function set_updated_at();

-- SOURCE: 20260716120300_ownership_policy_learning.sql
-- Original SHA-256: 4c6024870effbb9dc94c144c7d9d950c02e1badff4857f76f91c496e9f155c75
-- ============================================================================
-- Universal Intelligence Foundation — P3/P4/P5 OWNERSHIP · POLICY · LEARNING
-- ============================================================================
-- Ownership as polymorphic RACI edges (§5). Policy as versioned declarative
-- decision tables with a pure evaluator; every evaluation logged for replay
-- (§6). Confidence routing is a policy OUTPUT (review_tasks). Learning stores
-- immutable corrections that PROPOSE versioned deltas, never overwrite (§7).
-- ============================================================================

-- ── Ownership (RACI + waiting_on + approver + observer), polymorphic party. ─
create table if not exists ownership_assignments (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references tenants(id) on delete cascade,
  object_id   uuid not null references intelligence_objects(id) on delete cascade,
  raci_role   text not null
                check (raci_role in ('responsible','accountable','consulted','informed','waiting_on','approver','observer')),
  party_kind  text not null
                check (party_kind in ('user','role','department','team','customer','supplier','engineer','external','ai_agent','automation')),
  party_ref   text not null,                  -- user uuid | role slug | org_unit id | graph_node id | agent/automation id
  assigned_by text,
  assigned_at timestamptz not null default now(),
  unique (object_id, raci_role, party_kind, party_ref)
);
create index if not exists oa_object on ownership_assignments (object_id);
create index if not exists oa_party  on ownership_assignments (tenant_id, party_kind, party_ref);

-- ── Policy: ordered declarative rules, evaluated PURELY. Config, not code. ───
create table if not exists policies (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid references tenants(id) on delete cascade,   -- null = platform/industry/domain default
  domain      text not null,
  scope_kind  text not null check (scope_kind in ('platform','industry','domain','tenant')),
  name        text not null,
  rules       jsonb not null default '[]',    -- [{when:<condition-tree>, then:<effects>}], ordered
  priority    int  not null default 100,      -- evaluation order across policies (lower = earlier)
  enabled     boolean not null default true,
  version_id  uuid not null references config_versions(id),
  created_at  timestamptz not null default now()
);
create index if not exists policies_lookup on policies (domain, scope_kind, enabled, priority);

-- ── Decision log — the backbone of routing, learning AND simulation (§6.1). ─
create table if not exists decision_log (
  id                     uuid primary key default gen_random_uuid(),
  tenant_id              uuid not null references tenants(id) on delete cascade,
  object_id              uuid not null,                  -- soft ref (object may be re-evaluated)
  object_snapshot        jsonb not null,                 -- inputs AS THEY WERE (replayability)
  effective_profile_hash text not null,
  policy_version_ids     uuid[] not null default '{}',
  matched_rules          jsonb not null default '[]',    -- which rules fired + why
  outputs                jsonb not null default '{}',    -- owner, priority, deadline, route, ...
  input_hash             text not null,                  -- hash(snapshot + profile_hash + policy_versions)
  evaluated_at           timestamptz not null default now()
);
create index if not exists decision_log_object on decision_log (tenant_id, object_id, evaluated_at);
create index if not exists decision_log_window on decision_log (tenant_id, evaluated_at);

-- ── Confidence routing output — human review queue (OpenFolk / tenant / manual). ─
create table if not exists review_tasks (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references tenants(id) on delete cascade,
  object_id   uuid not null references intelligence_objects(id) on delete cascade,
  route       text not null check (route in ('openfolk','tenant_senior','manual')),
  reason      text,
  decision_id uuid,
  status      text not null default 'pending' check (status in ('pending','claimed','resolved','dismissed')),
  claimed_by  text,
  resolved_by text,
  resolution  jsonb,
  resolved_at timestamptz,
  created_at  timestamptz not null default now()
);
create index if not exists review_tasks_queue on review_tasks (route, status, created_at);

-- ── Learning: immutable corrections → PROPOSED versioned deltas (§7). ───────
create table if not exists corrections (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references tenants(id) on delete cascade,
  object_id       uuid,
  decision_id     uuid,
  before          jsonb not null,
  after           jsonb not null,
  correction_kind text not null
                    check (correction_kind in ('engine_mistake','tenant_preference','industry_preference','new_pattern')),
  scope_hint      text,                          -- which layer a resulting adjustment should target
  actor           text not null,
  review_level    text,
  proposed_version_id uuid references config_versions(id),  -- the delta this correction proposes (if any)
  created_at      timestamptz not null default now()
);
create index if not exists corrections_lookup on corrections (tenant_id, correction_kind, created_at);

-- ── RLS ─────────────────────────────────────────────────────────────────────
alter table ownership_assignments enable row level security;
drop policy if exists oa_select on ownership_assignments;
create policy oa_select on ownership_assignments for select to authenticated
  using (tenant_id = current_tenant_id() or is_openfolk());

alter table decision_log enable row level security;
drop policy if exists dl_select on decision_log;
create policy dl_select on decision_log for select to authenticated
  using (tenant_id = current_tenant_id() or is_openfolk());

alter table corrections enable row level security;
drop policy if exists corr_select on corrections;
create policy corr_select on corrections for select to authenticated
  using (tenant_id = current_tenant_id() or is_openfolk());

-- Policies are provider-managed config; review queue is provider + tenant-senior.
alter table policies enable row level security;
drop policy if exists policies_select on policies;
create policy policies_select on policies for select to authenticated
  using (tenant_id is null or tenant_id = current_tenant_id() or is_openfolk());

alter table review_tasks enable row level security;
drop policy if exists review_tasks_select on review_tasks;
create policy review_tasks_select on review_tasks for select to authenticated
  using (tenant_id = current_tenant_id() or is_openfolk());

-- SOURCE: 20260818120000_operational_ownership.sql
-- Original SHA-256: b342409c7aca36fe344dba6c6c925c2c8b8296c817d46761443dcf634aa8e995
-- ServiceOS — Operational roles, responsibilities, ownership & authority (universal).
--
-- The platform had two disconnected notions of "role": the coarse auth role
-- (`profiles.role` = owner|admin|ops|viewer) and RACI `ownership_assignments` bound
-- to intelligence_objects only. Neither models a person's OPERATIONAL role, who
-- owns which objective/workflow/team, weekday-dependent cover, or the AUTHORITY to
-- govern agents/automations. This adds that layer, universally.
--
-- Design rules honoured:
--  - `profiles.role` stays AUTHORIZATION; operational role/responsibility lives here.
--  - formal role vs OBSERVED role are distinct; observed starts proposed/inferred.
--  - tenant-scoped, RLS-read, service-role-write, versioned, effective-date-aware.
--  - NO tenant data is seeded here (universal engine only). Drummond drafts are a
--    separate, reversible, `openfolk_proposed` data seed.
--
-- Rollback:
--   drop table if exists authority_grants;
--   drop table if exists responsibility_assignments;
--   drop table if exists team_members;
--   drop table if exists authority_permissions;

-- ── Team members: the person + formal role + OBSERVED role ──────────────────
create table if not exists team_members (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references tenants(id) on delete cascade,
  profile_id      uuid,                              -- profiles.id when they have a login (nullable; staff may have none)
  display_name    text not null,
  org_unit_id     uuid references org_units(id) on delete set null,
  formal_role     text,                              -- official job title / role
  observed_role   text,                              -- what they actually do (inferred from evidence)
  observed_status text not null default 'proposed'
                    check (observed_status in ('proposed','inferred','confirmed')),
  authority_level text not null default 'individual'
                    check (authority_level in ('individual','lead','manager','director','owner')),
  confidence      numeric check (confidence is null or (confidence between 0 and 1)),
  evidence        jsonb not null default '[]',
  source          text not null default 'openfolk_proposed',
  confirmed_by    uuid,
  confirmed_at    timestamptz,
  effective_from  timestamptz not null default now(),
  effective_to    timestamptz,                       -- null = current
  version         int not null default 1,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index if not exists team_members_tenant on team_members (tenant_id, effective_to);
create index if not exists team_members_profile on team_members (tenant_id, profile_id);
drop trigger if exists team_members_set_updated_at on team_members;
create trigger team_members_set_updated_at before update on team_members
  for each row execute function set_updated_at();

-- ── Responsibilities / ownership: many per person, shared, weekday, cover ────
create table if not exists responsibility_assignments (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references tenants(id) on delete cascade,
  member_id      uuid not null references team_members(id) on delete cascade,
  kind           text not null
                   check (kind in ('responsibility_area','objective','workflow','escalation','team','customer_segment','cover')),
  target_ref     text,                               -- objective_id | workflow key | org_unit id | area label | covered member_id
  label          text not null,                      -- human description
  raci_role      text not null default 'responsible'
                   check (raci_role in ('responsible','accountable','consulted','informed','approver','observer')),
  is_shared      boolean not null default false,
  weekday_mask   int,                                -- bitmask Mon=1,Tue=2,…,Sun=64; null = all days
  cover_for      uuid references team_members(id) on delete set null,
  confidence     numeric check (confidence is null or (confidence between 0 and 1)),
  evidence       jsonb not null default '[]',
  source         text not null default 'openfolk_proposed',
  confirmed      boolean not null default false,
  effective_from timestamptz not null default now(),
  effective_to   timestamptz,
  version        int not null default 1,
  created_at     timestamptz not null default now()
);
create index if not exists resp_member on responsibility_assignments (tenant_id, member_id, effective_to);
create index if not exists resp_target on responsibility_assignments (tenant_id, kind, target_ref);

-- ── Authority: agent/automation governance + approval/assign, by scope ──────
create table if not exists authority_permissions (
  permission  text primary key,
  category    text not null,
  description text not null
);
insert into authority_permissions (permission, category, description) values
  -- agent / automation governance (the twelve agent controls)
  ('agent.view','agent','View assigned agents'),
  ('agent.interact','agent','Interact with an assigned agent'),
  ('agent.correct','agent','Correct agent output / provide context'),
  ('agent.approve_action','agent','Approve a proposed agent action'),
  ('agent.pause','agent','Pause an agent'),
  ('agent.configure','agent','Configure agent behaviour'),
  ('agent.create','agent','Create an agent'),
  ('agent.activate','agent','Activate / deactivate an agent'),
  ('agent.set_autonomy','agent','Change autonomy level'),
  ('agent.set_access','agent','Change tools / data access'),
  ('agent.assign','agent','Assign agents to users / teams / roles'),
  ('agent.retire','agent','Retire an agent'),
  -- work / strategy authority
  ('work.approve','work','Approve work / actions within authority'),
  ('work.assign','work','Assign work to others'),
  ('objective.publish','strategy','Publish / activate objectives'),
  ('ownership.confirm','strategy','Confirm roles / ownership')
on conflict (permission) do nothing;

create table if not exists authority_grants (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references tenants(id) on delete cascade,
  member_id      uuid not null references team_members(id) on delete cascade,
  permission     text not null references authority_permissions(permission),
  scope          text not null default 'self' check (scope in ('self','team','company')),
  scope_ref      text,                               -- org_unit id when scope='team'
  source         text not null default 'openfolk_proposed',
  confirmed      boolean not null default false,
  effective_from timestamptz not null default now(),
  effective_to   timestamptz,
  created_at     timestamptz not null default now()
);
-- one active grant per (member, permission, scope, scope_ref)
create unique index if not exists authority_grants_uk
  on authority_grants (tenant_id, member_id, permission, scope, coalesce(scope_ref, ''));

-- ── RLS: tenant-scoped read for authenticated; writes are service-role only ──
alter table team_members enable row level security;
alter table responsibility_assignments enable row level security;
alter table authority_permissions enable row level security;
alter table authority_grants enable row level security;

drop policy if exists team_members_select on team_members;
create policy team_members_select on team_members
  for select to authenticated using (tenant_id = current_tenant_id());

drop policy if exists resp_select on responsibility_assignments;
create policy resp_select on responsibility_assignments
  for select to authenticated using (tenant_id = current_tenant_id());

drop policy if exists authority_grants_select on authority_grants;
create policy authority_grants_select on authority_grants
  for select to authenticated using (tenant_id = current_tenant_id());

drop policy if exists authority_permissions_select on authority_permissions;
create policy authority_permissions_select on authority_permissions
  for select to authenticated using (true); -- platform vocabulary

-- SOURCE: 20260814120000_universal_imports_and_jobs.sql
-- Original SHA-256: 911717fc61c1575cb398210671d962f09084c35b3cae2f75e1f76ba3c02b51c2
-- ServiceOS — Universal data imports + canonical Jobs/Sites (additive, tenant-scoped).
--
-- Two things, both source-neutral:
--  1) Canonical SoR tables the business graph can project: `jobs` (+ `job_number_aliases`)
--     and `sites`. Engineers are `people` (role), not a new type. Job numbers are unique per
--     (tenant, source_system) namespace — NOT globally. interactions.related_job_id already
--     exists as the link column; business-graph-sync will project jobs as node_type='job'.
--  2) A universal import engine: `import_profiles` (reusable, source-neutral column mapping —
--     Commusoft mapping is a PROFILE ROW, never generic code), `data_imports` (one row per
--     import run with full counts + provenance), `import_row_provenance` (per-entity lineage
--     so no canonical record loses where it came from). Plus a private `imports` Storage bucket.
--
-- Never overwrite stronger canonical data with lower-confidence imported values — enforced in
-- the import engine (evidence + confidence per row), recorded in import_row_provenance.
-- RLS: tenant SELECT for authenticated; writes service-role only. Explicit grants for portability.
--
-- ROLLBACK: drop tables job_number_aliases, jobs, sites, import_row_provenance, data_imports,
--   import_profiles;  delete from storage.buckets where id='imports';

-- ── Canonical Sites (SoR) ───────────────────────────────────────────────────
create table if not exists sites (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null,
  source_system text,                         -- e.g. commusoft (null = native)
  external_id   text,                          -- provider site id
  company_id    uuid references companies (id) on delete set null,
  person_id     uuid references people (id) on delete set null,
  label         text,
  address_text  text,
  postcode      text,
  metadata      jsonb not null default '{}'::jsonb,
  created_source text not null default 'native',
  verified      boolean not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create unique index if not exists sites_source_uk
  on sites (tenant_id, source_system, external_id) where external_id is not null;
create index if not exists sites_tenant_idx on sites (tenant_id);
create index if not exists sites_tenant_postcode_idx on sites (tenant_id, postcode);

-- ── Canonical Jobs (SoR) ────────────────────────────────────────────────────
create table if not exists jobs (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null,
  source_system      text,                     -- commusoft | native | …
  external_id        text,                      -- provider job id (stable)
  job_number         text,                      -- human job number (tenant/source-scoped)
  customer_person_id uuid references people (id) on delete set null,
  customer_company_id uuid references companies (id) on delete set null,
  site_id            uuid references sites (id) on delete set null,
  engineer_person_id uuid references people (id) on delete set null,   -- engineer = a person
  title              text,
  description        text,
  job_type           text,
  status             text,                      -- free text (source vocab), e.g. open|completed
  priority           text,
  invoice_status     text,
  quote_status       text,
  value_pennies      bigint,                    -- money as integer pennies (never float)
  created_date       timestamptz,
  booked_date        timestamptz,
  completed_date     timestamptz,
  active             boolean not null default true,
  metadata           jsonb not null default '{}'::jsonb,
  created_source     text not null default 'native',
  verified           boolean not null default false,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
-- Idempotent import: one job per (tenant, source_system, external_id).
create unique index if not exists jobs_source_uk
  on jobs (tenant_id, source_system, external_id) where external_id is not null;
-- Job number unique within the (tenant, source_system) namespace — not global.
create unique index if not exists jobs_number_uk
  on jobs (tenant_id, source_system, job_number) where job_number is not null;
create index if not exists jobs_tenant_idx on jobs (tenant_id);
create index if not exists jobs_tenant_customer_idx on jobs (tenant_id, customer_person_id);

-- ── Job-number aliases (formatting variants → canonical job) ─────────────────
-- '#123456', 'Job 123456', 'J123456', 'Commusoft 123456' all normalise to one job.
create table if not exists job_number_aliases (
  id         uuid primary key default gen_random_uuid(),
  tenant_id  uuid not null,
  job_id     uuid not null references jobs (id) on delete cascade,
  alias      text not null,             -- as written
  normalized text not null,             -- canonical digits (e.g. '123456')
  source     text not null default 'import',
  created_at timestamptz not null default now()
);
create unique index if not exists job_number_aliases_norm_uk
  on job_number_aliases (tenant_id, normalized);
create index if not exists job_number_aliases_job_idx on job_number_aliases (tenant_id, job_id);

-- ── Import profiles (source-neutral; Commusoft mapping is a ROW) ─────────────
create table if not exists import_profiles (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid,                    -- null = platform default profile
  source_system text not null,           -- commusoft | generic | …
  entity_type   text not null,           -- customers | jobs | staff | sites | assets
  name          text not null,
  -- definition: { columns:[{canonical, aliases[], required, type, transform}],
  --   identifier_rules[], dedup_rules[], relationship_rules[], date_formats[], … }
  definition    jsonb not null default '{}'::jsonb,
  active        boolean not null default true,
  version       int not null default 1,
  created_by    uuid,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index if not exists import_profiles_tenant_idx
  on import_profiles (tenant_id, source_system, entity_type) where active;

-- ── Import runs (one per upload; full counts + provenance) ───────────────────
create table if not exists data_imports (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null,
  source_system     text not null,
  profile_id        uuid references import_profiles (id) on delete set null,
  entity_type       text not null,
  original_filename text,
  file_checksum     text,                -- sha256 — duplicate-upload detection
  file_size         bigint,
  storage_path      text,                -- private bucket pointer (raw file retained, controlled)
  status            text not null default 'uploaded',
    -- uploaded | previewed | importing | completed | failed
  row_count         int not null default 0,
  valid_rows        int not null default 0,
  invalid_rows      int not null default 0,
  created_records   int not null default 0,
  updated_records   int not null default 0,
  skipped_records   int not null default 0,
  duplicate_records int not null default 0,
  conflict_records  int not null default 0,
  preview           jsonb,               -- dry-run summary (redacted)
  failure           text,
  import_version    int not null default 1,
  uploaded_by       uuid,
  started_at        timestamptz,
  completed_at      timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create index if not exists data_imports_tenant_idx on data_imports (tenant_id, created_at desc);
create index if not exists data_imports_checksum_idx on data_imports (tenant_id, file_checksum);

-- ── Per-entity import provenance (lineage for every created/updated record) ──
create table if not exists import_row_provenance (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null,
  import_id        uuid not null references data_imports (id) on delete cascade,
  entity_table     text not null,        -- people | companies | jobs | sites | …
  entity_id        uuid not null,
  source_system    text,
  source_row_number int,
  external_id      text,
  imported_fields  text[] not null default '{}',
  match_strategy   text,                 -- external_id | phone | email | job_number | new | …
  confidence       numeric,
  action           text,                 -- created | updated | skipped | conflict
  conflicts        jsonb not null default '[]'::jsonb,
  imported_at      timestamptz not null default now()
);
create index if not exists import_row_provenance_import_idx on import_row_provenance (tenant_id, import_id);
create index if not exists import_row_provenance_entity_idx on import_row_provenance (tenant_id, entity_table, entity_id);

-- Storage bucket and domain registry mutation deferred to the import release.
-- ── triggers + RLS + grants ─────────────────────────────────────────────────
do $$
declare t text;
begin
  foreach t in array array[
    'sites','jobs','job_number_aliases','import_profiles','data_imports','import_row_provenance'
  ] loop
    execute format('drop trigger if exists %1$s_set_updated_at on %1$s;', t);
    -- job_number_aliases + import_row_provenance have no updated_at → guard
    if exists (select 1 from information_schema.columns
                 where table_name = t and column_name = 'updated_at') then
      execute format('create trigger %1$s_set_updated_at before update on %1$s
                        for each row execute function set_updated_at();', t);
    end if;
    execute format('alter table %s enable row level security;', t);
    execute format('drop policy if exists %1$s_select_tenant on %1$s;', t);
    -- platform-default import_profiles (tenant_id null) are readable by any authenticated tenant
    if t = 'import_profiles' then
      execute format('create policy %1$s_select_tenant on %1$s
                        for select to authenticated
                        using (tenant_id is null or tenant_id = current_tenant_id());', t);
    else
      execute format('create policy %1$s_select_tenant on %1$s
                        for select to authenticated using (tenant_id = current_tenant_id());', t);
    end if;
    execute format('grant select, insert, update, delete on %s to service_role;', t);
    execute format('grant select on %s to authenticated;', t);
  end loop;
end $$;

